-- D12 written comment with the star rating: DEV application candidate. NOT APPLIED. It needs the owner's explicit "primeni" that NAMES the closure-certificate re-bind (a privacy certification of the erasure program, AGENTS 3.1.4).
-- GENERATED by supabase/proofs/d12/build_d12.py from supabase/proofs/d12/sql/*, d12_pins.json (read-only DEV pins) and d12_preimage.json (read-only DEV pre-image): do not edit by hand (`--check` fails on any difference).
-- {{PROVENANCE}}
-- One atomic DO statement: exact DEV predecessor pins (complete metadata and LF-normalised bodies; owner, ACL, security and configuration of the three composite-typed functions; the exact shape of the immutable star table), the new private table with
-- its triggers, the new functions (the legacy review functions are NOT touched), the exact-once anchor edits of the three certified closure functions and of the three export functions, the one retention-catalog row and the one retention-class
-- description (a catalog TEXT: it names the new free text and sets no period), an isolation probe that proves the digest moved because of THIS change only, the three-place re-bind computed inside the same transaction, and an exact delta accounting
-- (every old function is unchanged except the six edited ones and the readiness constant, exactly the six reviewed new functions exist, every catalog surface is unchanged except the reviewed additions).
-- TRANSPORT: this file is ASCII-only and carries no unicode escape text (every character class is built with chr()), so a connector that resolves escapes cannot change a stored text or a pinned md5. Send it behind the integrity guard that
-- `build_d12.py --wrap` generates: the database then proves that the statement it received is the proved one, byte for byte.
-- Conflicts raise PT409, never the SQLSTATE that PostgREST 14 re-executes without end (registry blocker B24); no new body mentions that SQLSTATE at all.
do $d12_application$
declare
  pin record; prior record; actual jsonb; before_surface jsonb; after_surface jsonb; expected_datasets jsonb; before_default_acls text; star_before text; star_after text;
  old_source text; new_source text; ready_definition text; edit_definition text; source_row jsonb; erasure_row jsonb; affected integer; rewritten oid[]; fresh oid[]; diff_keys text;
  pre_relations text; pre_scope text; pre_patch text; probe_message text; probe_digest text; expected_classes jsonb;
  surface_query text := $surface_query${{SURFACE_QUERY}}$surface_query$;
begin
  perform set_config('lock_timeout','5s',true);
  perform set_config('statement_timeout','120s',true);
  perform set_config('search_path','pg_catalog',true);
  if current_user<>'postgres' then raise exception 'D12_APPLICATION_OWNER_REQUIRED' using errcode='55000';end if;
  -- Hold closure writes and review writes until this atomic change commits: a check without these locks could admit a closure or a review between the check and the certificate replacement.
  lock table private.closure_executions_v5 in share mode;
  lock table private.closure_source_v5,private.closure_erasure_source_v5,private.closure_dataset_catalog_v5 in share row exclusive mode;
  lock table private.agreement_reviews in share row exclusive mode;
  lock table private.retention_data_classes in share row exclusive mode;
  -- The predecessor shape of the immutable star table, re-checked INSIDE this transaction (a preflight may be hours old): columns, constraints, triggers, ACL, forced RLS, no policy.
  if {{STAR_TABLE_BAD}} then
    raise exception 'D12_APPLICATION_STAR_TABLE_DRIFT' using errcode='55000';end if;
  if exists(select 1 from private.closure_executions_v5 where state='EXECUTING') then
    raise exception 'D12_APPLICATION_CLOSURE_IN_FLIGHT' using errcode='55000';end if;
  if (select count(*) from private.closure_source_v5)<>1 or (select count(*) from private.closure_erasure_source_v5)<>1 then
    raise exception 'D12_APPLICATION_CERTIFICATE_CARDINALITY' using errcode='55000';end if;
  if to_regclass('private.{{TABLE}}') is not null
     or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in({{NEW_FUNCTION_NAME_PAIRS}}))
     or exists(select 1 from pg_trigger where tgname in({{TRIGGER_NAME_LIST}}))
     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in({{INDEX_NAME_LIST}})) then
    raise exception 'D12_APPLICATION_ALREADY_PRESENT' using errcode='55000';end if;
  -- The retention class text this change appends to is exactly the predecessor text (a catalog row, no trigger, not hashed by any certified function).
  if (select description from private.retention_data_classes where code='{{RETENTION_CLASS_CODE}}' and required and active) is distinct from {{RETENTION_DESCRIPTION_OLD}} then
    raise exception 'D12_APPLICATION_RETENTION_CLASS_PREDECESSOR_DRIFT' using errcode='55000';end if;
  -- Exact DEV predecessor metadata: every function this change rewrites, replaces, calls or leaves untouched on purpose.
  for pin in select * from (values
{{METADATA_PINS}}
  ) p(signature,metadata_md5) loop
    if (select md5(((to_jsonb(p)-'oid'-'pronamespace'-'proowner'-'prolang'-'proacl'-'prosrc')
        ||jsonb_build_object('namespace',n.nspname,'owner',pg_get_userbyid(p.proowner),
          'language',l.lanname,'acl',p.proacl::text))::text)
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
      where p.oid=to_regprocedure(pin.signature)) is distinct from pin.metadata_md5 then
      raise exception 'D12_APPLICATION_METADATA_DRIFT: %',pin.signature using errcode='55000';end if;
  end loop;
  -- (The functions with a composite argument or result type are pinned by body only: their metadata carries a per-database type OID and cannot be portable.)
  -- Exact DEV predecessor BODIES (LF-normalised). The readiness body is pinned below after replacing only its one certified literal.
  for pin in select * from (values
{{BODY_PINS}}
  ) p(signature,body_md5) loop
    if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5 then
      raise exception 'D12_APPLICATION_BODY_DRIFT: %',pin.signature using errcode='55000';end if;
  end loop;
  -- The three composite-typed functions: owner, ACL, security, configuration, volatility, strictness, language and result (their body is pinned above; their full metadata hash carries a per-database type OID and cannot be portable).
  for pin in select * from (values
{{COMPOSITE_PINS}}
  ) p(signature,acl,config,definer,volatility,language_name,result_type,strict_function) loop
    if not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and {{COMPOSITE_PREDICATE}}) then
      raise exception 'D12_APPLICATION_COMPOSITE_METADATA_DRIFT: %',pin.signature using errcode='55000';end if;
  end loop;
  -- Certificate and readiness: certified in all three places, equal to the live digest, ready, bound.
  select to_jsonb(c),sha256 into source_row,old_source from private.closure_source_v5 c where singleton;
  select to_jsonb(c) into erasure_row from private.closure_erasure_source_v5 c where singleton;
  select pg_get_functiondef(p.oid) into ready_definition from pg_proc p where oid='private.retention_ai_source_ready()'::regprocedure;
  if old_source is null or old_source is distinct from private.closure_source_digest_v5() or old_source is distinct from erasure_row->>'sha256'
     or private.retention_ai_source_ready() is distinct from true or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from old_source then
    raise exception 'D12_APPLICATION_CLOSURE_PREDECESSOR_NOT_READY' using errcode='55000';end if;
  if not exists(select 1 from pg_proc where oid='private.retention_ai_source_ready()'::regprocedure
      and (length(prosrc)-length(replace(prosrc,old_source,'')))=length(old_source)
      and md5(replace(replace(prosrc,E'\r\n',E'\n'),old_source,'__CERTIFIED_SOURCE__'))='{{READINESS_PLACEHOLDER_MD5}}') then
    raise exception 'D12_APPLICATION_READINESS_PREDECESSOR_DRIFT' using errcode='55000';end if;
  if (length(ready_definition)-length(replace(ready_definition,old_source,'')))<>length(old_source)
     or (select count(*) from regexp_matches(ready_definition,'[0-9a-f]{64}','g'))<>1 then
    raise exception 'D12_APPLICATION_READINESS_LITERAL_DRIFT' using errcode='55000';end if;
  -- The roster, the catalog row and the review table are exactly what the design expects before the change.
  if cardinality(private.closure_redaction_relations_v5())<>{{ROSTER_BEFORE}}
     or 'private.agreement_reviews'=any(private.closure_redaction_relations_v5())
     or 'private.{{TABLE}}'=any(private.closure_redaction_relations_v5())
     or (select relations from private.closure_dataset_catalog_v5 where data_class='AGREEMENT_REVIEWS') is distinct from array['private.agreement_reviews']::text[]
     or jsonb_array_length(private.data_export_dataset_catalog())<>52
     or private.data_export_projection_sha_v5() is distinct from '{{PROJECTION_SHA_BEFORE}}' then
    raise exception 'D12_APPLICATION_ROSTER_OR_CATALOG_PREDECESSOR_DRIFT' using errcode='55000';end if;
  -- What the isolation probe needs: the three certified definitions exactly as they are now.
  pre_relations:=pg_get_functiondef('private.closure_redaction_relations_v5()'::regprocedure);
  pre_scope:=pg_get_functiondef('private.closure_redaction_scope_v5(text)'::regprocedure);
  pre_patch:=pg_get_functiondef('private.closure_redaction_patch_v5(text,jsonb,uuid,uuid)'::regprocedure);
  execute surface_query into before_surface;
  select string_agg(defaclnamespace::regnamespace::text||':'||defaclobjtype::text||':'||defaclacl::text,' | ' order by defaclnamespace::regnamespace::text,defaclobjtype::text) into before_default_acls from pg_default_acl;
  create temporary table d12_application_functions on commit drop as
    select p.oid,p.oid::regprocedure::text signature,to_jsonb(p) metadata
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in('public','private','rls_private');
  select jsonb_agg(case when c.data_class='AGREEMENT_REVIEWS' then
    jsonb_set(to_jsonb(c),'{relations}',to_jsonb(c.relations||array['private.{{TABLE}}']::text[]))
    else to_jsonb(c) end order by data_class) into expected_datasets from private.closure_dataset_catalog_v5 c;
  select md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by r.id),'')) into star_before from private.agreement_reviews r;
  select jsonb_agg(case when c.code='{{RETENTION_CLASS_CODE}}' then jsonb_set(to_jsonb(c),'{description}',to_jsonb({{RETENTION_DESCRIPTION_NEW}}::text)) else to_jsonb(c) end order by c.code)
    into expected_classes from private.retention_data_classes c;
  rewritten:=array[{{REWRITTEN_ROSTER}}]::oid[];
  if cardinality(rewritten)<>{{REWRITTEN_COUNT}} or array_position(rewritten,null) is not null then raise exception 'D12_APPLICATION_REWRITTEN_ROSTER' using errcode='55000';end if;

  -- 1. The private table: one row per review that carries a comment, keyed by the review (so "at most one comment per review" is the primary key), nothing client-reachable.
{{TABLE_DDL}}

  -- 2. The new functions. The legacy review functions are not touched: every installed build keeps its star-only path with no new error name.
{{FUNCTION_DDL}}

  -- 3. The certified erasure program and the export: each edit is ONE exact replace on the current definition, the anchor having been pinned to occur exactly once.
{{EDIT_DDL}}
  update private.closure_dataset_catalog_v5 set relations=relations||array['private.{{TABLE}}']::text[] where data_class='AGREEMENT_REVIEWS' and relations=array['private.agreement_reviews']::text[];
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_APPLICATION_CATALOG_ROW_COUNT' using errcode='55000';end if;
  -- The class text: the optional free text now lives in the class AGREEMENT_REVIEWS, so its description says so (it states what is implemented and sets no retention period). ONE row, pinned by its old text.
  update private.retention_data_classes set description={{RETENTION_DESCRIPTION_NEW}} where code='{{RETENTION_CLASS_CODE}}' and required and active and description={{RETENTION_DESCRIPTION_OLD}};
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_APPLICATION_RETENTION_CLASS_ROW_COUNT' using errcode='55000';end if;

  -- 4. The rewritten bodies, exactly: the md5 (LF-normalised) each body must have after this change. They are computed by the generator from the pinned DEV pre-image and the same anchor replacements,
  -- so on DEV, whose predecessor bodies are pinned above, the exact-once replacements can only produce these bytes.
  for pin in select * from (values
{{REWRITTEN_BODY_PINS}}
  ) p(signature,body_md5) loop
    if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5 then
      raise exception 'D12_APPLICATION_REWRITTEN_BODY_DELTA: %',pin.signature using errcode='55000';end if;
  end loop;
  if private.data_export_projection_sha_v5() is distinct from '{{PROJECTION_SHA_AFTER}}' then
    raise exception 'D12_APPLICATION_PROJECTION_SHA_DELTA' using errcode='55000';end if;

  -- 5. The certificate. The digest must have moved, and the certificate is UNCERTIFIED until the exact three-place re-bind below.
  new_source:=private.closure_source_digest_v5();
  if new_source is null or new_source=old_source or new_source!~'^[0-9a-f]{64}$' then
    raise exception 'D12_APPLICATION_NEW_SOURCE_INVALID' using errcode='55000';end if;
  if private.retention_ai_source_ready() is distinct from false or private.closure_erasure_binding_v5() is not null then
    raise exception 'D12_APPLICATION_UNCERTIFIED_STATE_NOT_CLOSED' using errcode='55000';end if;
  -- Isolation probe: undo ONLY the certified-surface change (the three edited certified definitions and the new table with its triggers) inside a nested block that is always rolled back,
  -- and read the digest there. It must be exactly the OLD certified value: the digest moved because of THIS change and nothing else (the new functions and the export edits are outside it).
  begin
    execute pre_relations;
    execute pre_scope;
    execute pre_patch;
    drop table private.{{TABLE}};
    raise exception 'D12_ISOLATION_PROBE' using errcode='55000',detail=private.closure_source_digest_v5();
  exception when sqlstate '55000' then
    get stacked diagnostics probe_message=message_text,probe_digest=pg_exception_detail;
    if probe_message is distinct from 'D12_ISOLATION_PROBE' then raise; end if;
  end;
  if probe_digest is distinct from old_source then
    raise exception 'D12_APPLICATION_DIGEST_NOT_ISOLATED: probe % old %',probe_digest,old_source using errcode='55000';end if;
  if to_regclass('private.{{TABLE}}') is null or pg_get_functiondef('private.closure_redaction_relations_v5()'::regprocedure) is not distinct from pre_relations then
    raise exception 'D12_APPLICATION_PROBE_NOT_ROLLED_BACK' using errcode='55000';end if;
  update private.closure_source_v5 set sha256=new_source where singleton and sha256=old_source;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_APPLICATION_SOURCE_ROW_COUNT' using errcode='55000';end if;
  update private.closure_erasure_source_v5 set sha256=new_source where singleton and sha256=old_source;
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'D12_APPLICATION_ERASURE_ROW_COUNT' using errcode='55000';end if;
  execute replace(ready_definition,old_source,new_source);

  -- Delta accounting 1/4: every old function is unchanged, except the readiness constant and the rewritten ones (their body only; owner, ACL, security, configuration and result stay).
  for prior in select * from d12_application_functions loop
    select to_jsonb(p) into actual from pg_proc p where oid=prior.oid;
    if actual is null then raise exception 'D12_APPLICATION_FUNCTION_REMOVED: %',prior.signature using errcode='55000';end if;
    if prior.oid='private.retention_ai_source_ready()'::regprocedure then
      if actual is distinct from jsonb_set(prior.metadata,'{prosrc}',to_jsonb(replace(prior.metadata->>'prosrc',old_source,new_source))) then
        raise exception 'D12_APPLICATION_READINESS_DELTA' using errcode='55000';end if;
    elsif prior.oid=any(rewritten) then
      if actual-'prosrc' is distinct from prior.metadata-'prosrc' then
        raise exception 'D12_APPLICATION_FUNCTION_AUTHORITY_DELTA: %',prior.signature using errcode='55000';end if;
      if actual->>'prosrc' is not distinct from prior.metadata->>'prosrc' then
        raise exception 'D12_APPLICATION_REWRITE_MISSING: %',prior.signature using errcode='55000';end if;
    elsif actual is distinct from prior.metadata then
      raise exception 'D12_APPLICATION_UNRELATED_FUNCTION_DELTA: %',prior.signature using errcode='55000';
    end if;
  end loop;
  -- Delta accounting 2/4: exactly the reviewed new functions exist, each with its exact body, language, volatility, security, result and ACL.
  select coalesce(array_agg(p.oid order by p.oid),'{}'::oid[]) into fresh from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in('public','private','rls_private') and not exists(select 1 from d12_application_functions old where old.oid=p.oid);
  if fresh is distinct from (select array_agg(to_regprocedure(x)::oid order by to_regprocedure(x)::oid) from unnest(array[{{NEW_FUNCTION_SIGNATURES}}]::text[]) x) then
    raise exception 'D12_APPLICATION_FUNCTION_ROSTER_DELTA' using errcode='55000';end if;
  for pin in select * from (values
{{NEW_FUNCTION_PINS}}
  ) p(signature,body_md5,language_name,volatility,definer,strict_function,result_type,acl) loop
    if not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and {{NEW_FUNCTION_PREDICATE}}) then
      raise exception 'D12_APPLICATION_NEW_FUNCTION_DELTA: %',pin.signature using errcode='55000';end if;
  end loop;
  -- Delta accounting 3/4: every table, column, constraint, trigger, policy, index and bucket is unchanged except the reviewed additions (the new table with everything it owns).
  execute surface_query into after_surface;
  if after_surface is distinct from before_surface then
    -- Name what differs (the key, how many entries each way and one example of each), so a refused application explains itself.
    select string_agg(k||': +'||(select count(*) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' -'||(select count(*) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)))::text
      ||' added '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(after_surface->k,'[]'::jsonb)) e where not(coalesce(before_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-')
      ||' removed '||coalesce((select left(e::text,240) from jsonb_array_elements(coalesce(before_surface->k,'[]'::jsonb)) e where not(coalesce(after_surface->k,'[]'::jsonb) @> jsonb_build_array(e)) limit 1),'-'),' | ')
      into diff_keys from jsonb_object_keys(before_surface) k where before_surface->k is distinct from after_surface->k;
    raise exception 'D12_APPLICATION_UNRELATED_CATALOG_DELTA: %',diff_keys using errcode='55000';
  end if;
  if (select string_agg(defaclnamespace::regnamespace::text||':'||defaclobjtype::text||':'||defaclacl::text,' | ' order by defaclnamespace::regnamespace::text,defaclobjtype::text) from pg_default_acl) is distinct from before_default_acls then
    raise exception 'D12_APPLICATION_DEFAULT_ACL_DELTA' using errcode='55000';end if;
  -- The new table, exactly: owner, flags, ACL, no policy, the columns (with their defaults), every constraint by name and kind, the two triggers, the two indexes.
  if {{TABLE_SHAPE_BAD}} then
    raise exception 'D12_APPLICATION_NEW_TABLE_DELTA' using errcode='55000';end if;
  if {{TRIGGERS_BAD}} then
    raise exception 'D12_APPLICATION_NEW_TRIGGER_DELTA' using errcode='55000';end if;
  -- Delta accounting 4/4: the retention catalog changed only by the new relation, the retention classes only by the one description, the star table is untouched, the certificate is bound in its three places and nothing else.
  if (select jsonb_agg(to_jsonb(c) order by data_class) from private.closure_dataset_catalog_v5 c) is distinct from expected_datasets then
    raise exception 'D12_APPLICATION_CATALOG_DELTA' using errcode='55000';end if;
  if (select jsonb_agg(to_jsonb(c) order by c.code) from private.retention_data_classes c) is distinct from expected_classes
     or (select count(*) from private.retention_data_classes where required and active)<>15 then
    raise exception 'D12_APPLICATION_RETENTION_CLASSES_DELTA' using errcode='55000';end if;
  -- The comment text must never be streamed: the new table is in no publication and no FOR ALL TABLES publication exists.
  if {{PUBLICATION_BAD}} then
    raise exception 'D12_APPLICATION_COMMENT_TABLE_PUBLISHED' using errcode='55000';end if;
  select md5(coalesce(string_agg(to_jsonb(r)::text,E'\n' order by r.id),'')) into star_after from private.agreement_reviews r;
  if star_after is distinct from star_before or exists(select 1 from private.{{TABLE}}) then
    raise exception 'D12_APPLICATION_STAR_OR_COMMENT_DATA_DELTA' using errcode='55000';end if;
  if cardinality(private.closure_redaction_relations_v5())<>{{ROSTER_AFTER}}
     or (private.closure_redaction_relations_v5())[{{ROSTER_AFTER}}] is distinct from 'private.{{TABLE}}'
     or private.closure_redaction_scope_v5('private.{{TABLE}}') is distinct from 't.author_account_id=$1'
     or private.closure_redaction_patch_v5('private.{{TABLE}}','{}'::jsonb,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid)
        is distinct from jsonb_build_object('operation','DELETE','patch','{}'::jsonb)
     or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews')
        is distinct from '["agreementId","createdAt","id","rating","tags","comment"]'::jsonb
     or jsonb_array_length(private.data_export_dataset_catalog())<>52 then
    raise exception 'D12_APPLICATION_CLOSURE_OR_EXPORT_POSTCONDITION' using errcode='55000';end if;
  if (select to_jsonb(c) from private.closure_source_v5 c where singleton) is distinct from jsonb_set(source_row,'{sha256}',to_jsonb(new_source))
    or (select to_jsonb(c) from private.closure_erasure_source_v5 c where singleton) is distinct from jsonb_set(erasure_row,'{sha256}',to_jsonb(new_source))
    or pg_get_functiondef('private.retention_ai_source_ready()'::regprocedure) is distinct from replace(ready_definition,old_source,new_source)
    or private.closure_source_digest_v5() is distinct from new_source
    or private.retention_ai_source_ready() is distinct from true
    or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from new_source then
    raise exception 'D12_APPLICATION_CERTIFIED_POSTCONDITION' using errcode='55000';end if;
  -- Authority: nothing reachable by anon; the three comment RPCs by authenticated only; the moderation function by the service role only; no client role on the table or on a private function.
  if exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
    or has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE')
    or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE')
    or exists(select 1 from unnest(array[{{NEW_FUNCTION_SIGNATURES}}]::text[]) x where has_function_privilege('anon',x,'EXECUTE'))
    or exists(select 1 from unnest(array[{{CLIENT_FUNCTION_SIGNATURES}}]::text[]) x where not has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
    or exists(select 1 from unnest(array[{{PRIVATE_FUNCTION_SIGNATURES}}]::text[]) x where has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
    or has_function_privilege('authenticated','{{SERVICE_FUNCTION_SIGNATURE}}','EXECUTE') or not has_function_privilege('service_role','{{SERVICE_FUNCTION_SIGNATURE}}','EXECUTE')
    or exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'private.{{TABLE}}','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) then
    raise exception 'D12_APPLICATION_FINAL_AUTHORITY_OR_STATE_DRIFT' using errcode='55000';end if;
  -- The new functions are visible to PostgREST without waiting for its next schema poll.
  perform pg_notify('pgrst','reload schema');
end
$d12_application$;
